import java.util.*;

class Solution {
  public String minInteger(String num, int k) {
    int n = num.length();
    ArrayDeque<Integer>[] pos = new ArrayDeque[10];
    for (int d = 0; d < 10; d++) pos[d] = new ArrayDeque<>();
    for (int i = 0; i < n; i++) pos[num.charAt(i) - '0'].add(i);
    Fenwick bit = new Fenwick(n);
    for (int i = 0; i < n; i++) bit.add(i, 1);
    StringBuilder out = new StringBuilder();
    for (int used = 0; used < n; used++) {
      for (int d = 0; d < 10; d++)
        if (!pos[d].isEmpty()) {
          int at = pos[d].peek();
          int cost = bit.sum(at);
          if (cost <= k) {
            k -= cost;
            out.append((char) ('0' + d));
            pos[d].poll();
            bit.add(at, -1);
            break;
          }
        }
    }
    return out.toString();
  }

  static class Fenwick {
    int[] t;

    Fenwick(int n) {
      t = new int[n + 1];
    }

    void add(int i, int v) {
      for (i++; i < t.length; i += i & -i) t[i] += v;
    }

    int sum(int i) {
      int s = 0;
      for (; i > 0; i -= i & -i) s += t[i];
      return s;
    }
  }
}
